def ordered(name, preferred, options, exclude=()):
    """Preferred names first, then the builder's default order; illegal or excluded names dropped."""
    first = [n for n in preferred if n in options and n not in exclude]
    return first + [n for n in spell_order(name, options) if n not in first and n not in exclude]


def book_for(level, options, order):
    """A legal Wizard spellbook that learns spells in the given order (default_book's acquisition rules)."""
    book = []
    for at in range(1, level + 1):
        eligible = {n: s for n, s in options.items() if 0 < s["level"] <= min(9, (at + 1) // 2)}
        picks = [n for n in order if n in eligible and n not in book]
        book += picks[:6 if at == 1 else 2]
        savant = [n for n in order if n in eligible and n not in book and eligible[n]["school"] == "evocation"]
        if at == 3: book += savant[:2]
        elif at in SAVANT_LEVELS: book += savant[:1]
    return book


def asis_for(name, level, profile, scores):
    if profile["method"] == "point_buy" or "flavour" not in profile:
        return default_asis(name, level, scores)
    result, scores = {}, scores.copy()
    for n in asi_levels(_class(name)):
        if n > level: continue
        add = {}
        for a in (PRIMARY[name], profile["flavour"]):
            a = next(x for x in (a, "con", *ABILITIES) if scores[x] < 20)
            scores[a] += 1; add[a] = add.get(a, 0) + 1
        result[n] = add
    return result


def recipe(name, level, profile_name):
    """A build recipe (the builds/*.yaml format) for one class, level and profile."""
    p = PROFILES[profile_name][name]
    primary = PRIMARY[name]
    background = {primary: 1, "con": 1, p["flavour"]: 1} if "flavour" in p else {primary: 2, "con": 1}
    scores = {a: min(20, p["abilities"][a] + background.get(a, 0)) for a in ABILITIES}
    row = _class(name)["levels"][level]
    choices = {"ability_method": p["method"], "background": background, "asis": asis_for(name, level, p, scores)}
    if name == "fighter" or name in {"paladin","ranger"} and level >= 2:
        choices["fighting_style"] = p["styles"][:1 + int(name == "fighter" and level >= 7)]
    if name in {"fighter", "rogue", "barbarian", "paladin", "ranger"}:
        choices["weapon_masteries"] = p["masteries"][:row["weapon_masteries"]]
    if name == "rogue" and level >= 5:
        choices["cunning_strike"] = p["cunning"] + ([("obscure" if profile_name == "optimized" else "daze")] if level >= 14 else [])
    if name == "cleric":
        choices.update(divine_order=p["order"], blessed_strikes=p["strike"])
    if name in {"wizard", "cleric", "paladin", "warlock", "bard", "ranger", "druid", "sorcerer"}:
        options = spell_options(name, level)
        cantrips = {n: s for n, s in options.items() if s["level"] == 0}
        choices["cantrips"] = ordered(name, p["cantrips"], cantrips)[:row["cantrips"]]
        leveled = {n: s for n, s in options.items() if s["level"] > 0}
        excluded = tuple(p.get("exclude", ()))
        # Excluded spells go last: they are learned or prepared only if nothing else is legal.
        order = ordered(name, p["spells"], leveled, excluded) + [n for n in excluded if n in leveled]
        if name == "wizard":
            book = book_for(level, options, order)
            validate_book(book, level, options, Validator("<preset>"))
            choices["spellbook"] = book
            available = set(book)
        else:
            # Domain spells are always prepared and may not be chosen again.
            probe = build(name, level, None, p["abilities"], p["equipment"], {k: v for k, v in choices.items() if k != "cantrips"} | {"cantrips": choices["cantrips"]})
            domain = set(probe["spells"]) - set(probe["prepared_spells"]) - set(choices["cantrips"])
            available = set(leveled) - domain
        choices["prepared_spells"] = high_first(name, [n for n in order if n in available], options, level)[:row["prepared"]]
    return {"class": name, "level": level, "subclass": SUBCLASSES[name], "abilities": dict(p["abilities"]),
            "equipment": p["equipment"], "choices": choices}


def preset_name(name, level, profile):
    return f"{name}_{level}" if profile == "standard" else f"{name}_{level}_{profile}"


def party(level, profile="standard"):
    """Build names for the four-class preset party at a level."""
    return [preset_name(name, level, profile) for name in ("fighter", "cleric", "rogue", "wizard")]


def write():
    folder = ROOT / "builds"
    for profile in PROFILES:
        for name in SUBCLASSES:
            for level in PRESET_LEVELS.get(name, LEVELS):
                d = recipe(name, level, profile)
                build(d["class"], d["level"], d["subclass"], d["abilities"], d["equipment"], d["choices"])
                (folder / f"{preset_name(name, level, profile)}.yaml").write_text(yaml.safe_dump(d, sort_keys=False), encoding="utf-8")


def main():
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--write", action="store_true", help="write the casual and optimized build files")
    args = parser.parse_args()
    if not args.write: parser.error("nothing to do; pass --write")
    write()
    print("wrote", sum(len(PRESET_LEVELS.get(name, LEVELS)) for name in SUBCLASSES for _ in PROFILES), "builds")


if __name__ == "__main__": main()
